const rec = $json;
const f = rec.fields || {};
const prevCount = (typeof f.ContactCount === 'number') ? f.ContactCount : 1;
const contactCount = prevCount + 1;
const isFinalAttempt = contactCount >= 3;

return {
  json: {
    recordId: rec.id,
    Name: f.Name || '',
    Email: f.Email || '',
    Company: f.Company || '',
    Interest: f.Interest || '',
    contactCount,
    isFinalAttempt
  }
};

